// Clawd at work — timing (P-2026-11-26.13, screen_specs §17 XP-Claude-Laptop).
// Pure: no Arduino, unit-tested on native. Frame bitmaps: clawd_work.h
// (generated by tools/clawdwork.py), indexed by the slots below.
//
// The top project goes "Đang chạy": the intro plays once (stand → wiggle →
// pull the laptop out → set it down → hop → sit), then the 3 typing frames
// loop. Leaving "Đang chạy" for Xong / an empty board puts Clawd straight to
// sleep (no packing away); for an approval / error, the awake mood Clawd.
//
// The intro's GIF timings (×1.5 = 90–300 ms) are rounded UP to the 200 ms
// channel tick (user's choice, 2026-11-26: keep the 5 Hz rule) → 200 / 400 ms,
// 3.0 s in all. Typing: 200 ms per frame.
#pragma once
#include <stdint.h>

namespace ClawdWork {

constexpr int kIntroFrames = 12;
// Slot in ClawdWorkBits::kFrame (order: GIF 0, 3, 4, 9, 11, 13, 14, 16, 17, 18, 19, 21, 22).
constexpr uint8_t  kIntroSlot[kIntroFrames] = {0, 1, 2, 1, 2, 3, 4, 5, 6, 7, 8, 9};
constexpr uint16_t kIntroMs[kIntroFrames]   = {400, 200, 200, 200, 200, 200, 400, 200, 400, 200, 200, 200};
constexpr int      kLoopFrames = 3;
constexpr uint8_t  kLoopSlot[kLoopFrames] = {10, 11, 12};
constexpr uint16_t kLoopMs = 200;

constexpr uint32_t introTotalMs() {
    uint32_t t = 0;
    for (int i = 0; i < kIntroFrames; i++) t += kIntroMs[i];
    return t;
}

// Frame slot to show `elapsedMs` after Clawd started working.
inline uint8_t slotAt(uint32_t elapsedMs) {
    uint32_t t = 0;
    for (int i = 0; i < kIntroFrames; i++) {
        t += kIntroMs[i];
        if (elapsedMs < t) return kIntroSlot[i];
    }
    return kLoopSlot[((elapsedMs - t) / kLoopMs) % kLoopFrames];
}

// Geometry (cells of 4 px; grid origin (136, 30); redraw region (132, 22)–(229, 83)).
constexpr int kCell = 4, kOriginX = 136, kOriginY = 30;

}  // namespace ClawdWork
